import XCTest

/// UI tests for the Pull Request section's unusable-`gh` warning.
///
/// Until now nothing — unit test or UI test — touched this copy, and it was a chain of
/// `status == .notInstalled` ternaries, so every state that wasn't "not found" printed "not signed
/// in". A version problem would have inherited a sign-in message that cannot fix it.
/// `PullRequestPanelCopyTests` pins the mapping; this pins that the panel actually renders it, through
/// the real gate at `PullRequestPanel.body`.
///
/// Driven by the `-WorkroomUITestGHStatus` seam. It has to exist because `refreshGitHubCLI` returns
/// immediately in fixture mode — it must, or a UI test would ask `gh` about the developer's own
/// machine — so before this there was no way to reach any warning state from a test.
///
/// Run with `make app-uitest` on a real GUI login session, or scoped:
/// `xcodebuild ... -only-testing:WorkroomAppUITests/PullRequestWarningUITests/<method>`.
final class PullRequestWarningUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp(ghStatus: String?) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    if let ghStatus { app.launchArguments += ["-WorkroomUITestGHStatus", ghStatus] }
    app.launch()
    app.activate()
    return app
  }

  /// A `Text` by exact label. Scoped to `staticTexts` rather than `.any` so the composed a11y labels
  /// of ancestor containers can't satisfy the assertion (the gotcha that makes `.any` matches lie).
  private func label(_ app: XCUIApplication, _ text: String) -> XCUIElement {
    app.staticTexts.matching(NSPredicate(format: "label == %@", text)).firstMatch
  }

  private func waitForChangesSection(_ app: XCUIApplication) {
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    XCTAssertTrue(
      app.descendants(matching: .any).matching(identifier: "inspector.header.Changes").firstMatch
        .waitForExistence(timeout: 10),
      "the Changes inspector section should exist")
  }

  /// An old gh must say so, and must NOT offer the "Install gh…" link — it is already installed, and
  /// the link buries the one-line upgrade that actually fixes it.
  func testTooOldRendersAnUpgradeWarningWithoutTheInstallLink() throws {
    let app = launchedApp(ghStatus: "tooOld")
    waitForChangesSection(app)

    XCTAssertTrue(
      label(app, "GitHub CLI too old").waitForExistence(timeout: 10),
      "the tooOld state should render its own title, not \u{201C}not signed in\u{201D}")
    XCTAssertFalse(
      label(app, "GitHub CLI not signed in").exists,
      "an old gh was described as a sign-in problem")
    XCTAssertFalse(
      app.links["Install gh\u{2026}"].exists, "gh is installed — the install link misdirects")
  }

  /// The state the reported bug produced falsely. Seeded here it SHOULD appear, with the login hint.
  func testNotAuthenticatedRendersTheSignInWarning() throws {
    let app = launchedApp(ghStatus: "notAuthenticated")
    waitForChangesSection(app)

    XCTAssertTrue(
      label(app, "GitHub CLI not signed in").waitForExistence(timeout: 10),
      "a genuinely signed-out gh should still warn")
    XCTAssertFalse(label(app, "GitHub CLI too old").exists)
    XCTAssertFalse(app.links["Install gh\u{2026}"].exists)
  }

  /// Missing gh is the one state where a download link is the fix.
  func testNotInstalledRendersTheInstallLink() throws {
    let app = launchedApp(ghStatus: "notInstalled")
    waitForChangesSection(app)

    XCTAssertTrue(
      label(app, "GitHub CLI not found").waitForExistence(timeout: 10),
      "a missing gh should say so")
    XCTAssertTrue(
      app.links["Install gh\u{2026}"].waitForExistence(timeout: 4),
      "the install link is the fix for a missing gh")
  }

  /// The default fixture launch (no seam argument) must warn about NOTHING. This is the regression
  /// guard for the bug itself at the UI layer: an optimistic `.available` default plus a fixture that
  /// never probes should leave the panel quiet.
  func testNoWarningWhenGHStatusIsNotSeeded() throws {
    let app = launchedApp(ghStatus: nil)
    waitForChangesSection(app)

    XCTAssertFalse(label(app, "GitHub CLI not signed in").exists)
    XCTAssertFalse(label(app, "GitHub CLI too old").exists)
    XCTAssertFalse(label(app, "GitHub CLI not found").exists)
  }
}

