/// Bring the Pull Request section into view and make sure its body is rendering.
///
/// The section is collapsible (`⌥⌘P`, bound to `store.prSectionCollapsed`), and a collapsed section
/// renders no body at all — so the warning would be genuinely absent for a reason that has nothing
/// to do with the copy. Clicking the header rather than sending the shortcut: a focused terminal
/// swallows key equivalents, and synthetic keystrokes are the least reliable way to drive this app.
private func revealPullRequestSection(_ app: XCUIApplication) {
  XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
  let header = app.descendants(matching: .any)
    .matching(identifier: "inspector.header.Pull Request").firstMatch
  XCTAssertTrue(
    header.waitForExistence(timeout: 10), "the Pull Request inspector section should exist")
  // Expand only if nothing from the body is on screen yet. The section's collapsed state persists
  // across launches (it round-trips through Defaults), so this must not assume either state.
  if !anyWarningVisible(app) && header.isHittable {
    header.click()
  }
}

